gloss=[('Akomodasi yang layak','Penyesuaian yang diperlukan agar peserta didik penyandang disabilitas dapat memperoleh akses dan partisipasi pendidikan sesuai kebutuhan.','anak-subjek'),('Asesmen formatif','Pengumpulan dan penggunaan informasi belajar untuk menentukan dukungan atau langkah berikutnya.','komponen'),('DAP','Praktik pendidikan yang mempertimbangkan pola perkembangan, keunikan individu, dan konteks; bukan sekadar kesesuaian usia.','anak-subjek'),('Fakta dan interpretasi','Fakta kasus menyatakan apa yang teramati atau diberikan; interpretasi memberi makna atau penjelasan yang masih perlu diperiksa.','profesional'),('Kurikulum tersembunyi','Pesan yang dipelajari melalui kebiasaan dan pengaturan kelas di luar tujuan tertulis.','budaya'),('Mesosistem','Hubungan antara lingkungan yang dialami anak secara langsung, misalnya rumah dan satuan PAUD.','lingkungan'),('Guided play','Bermain terbimbing: keaktifan dan pilihan anak hadir bersama tujuan serta dukungan pendidik.','bermain'),('Holistik-integratif','Pengembangan AUD melalui pemenuhan kebutuhan yang saling terkait dan koordinasi layanan lintas sektor.','paud'),('Landasan yuridis','Dasar hak, kewajiban, dan ketentuan hukum bagi penyelenggaraan pendidikan.','landasan'),('Partisipasi','Keterlibatan dan kesempatan menyampaikan suara atau mengambil tindakan yang bermakna.','anak-subjek'),('Refleksi profesional','Peninjauan tindakan pendidik menggunakan konsep, bukti, dan pertimbangan nilai untuk perbaikan.','profesional'),('Scaffolding','Bantuan belajar yang menanggapi kebutuhan tugas dan memungkinkan anak mengambil bagian; atribusi awal pada Wood, Bruner, dan Ross (1976).','pemikiran'),('Subjektifikasi','Dimensi tujuan pendidikan yang memperhatikan kemungkinan seseorang bertindak sebagai subjek dengan pertimbangan dan tanggung jawab.','tujuan'),('Tujuan dan indikator','Tujuan adalah arah kemampuan atau nilai; indikator merupakan petunjuk yang dipakai untuk membaca pencapaiannya.','tujuan'),('Zona perkembangan proksimal','Perbedaan antara kemampuan mandiri dan kemampuan melalui bimbingan atau kolaborasi yang sesuai dalam kerangka Vygotsky.','pemikiran')]
