b=heading('LABORATORIUM PENALARAN','Kasus dan aktivitas','Seluruh kasus bersifat ilustratif. Jangan memasukkan identitas anak nyata ke catatan atau repositori publik.')+'<div class="case-list">'+''.join(f'<section><span class="eyebrow">PERTEMUAN {l["slot"]:02}</span><h2>{e(l["question"])}</h2>{paras(l["case"])}<a href="{l["id"]}.html#latihan">Kerjakan aktivitas →</a> <a href="{l["id"]}.html#kembali">Baca arah analisis →</a></section>' for l in L)+'</div>'
write('kasus',b,title='Kasus dan aktivitas')
b=heading('SUMBER PENGETAHUAN','Referensi & regulasi','Bibliografi terarah dan keterangan penggunaan. Sumber untuk teori, bukti penelitian, dan ketentuan PAUD serta RA.')+'<aside class="pause"><strong>Gunakan sumber sesuai fungsi.</strong><p>Regulasi menetapkan ketentuan; teori membantu menjelaskan; penelitian memberi bukti dalam konteks tertentu; sumber normatif memberi arah nilai. Buku yang metadata atau deskripsinya diperiksa tidak diperlakukan seolah seluruh teksnya telah diaudit.</p></aside>'
